#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdio>
#include <iostream>
#include <numeric>
#include <random>
#include <string>
#include <unordered_map>
#include <vector>
using Clock=std::chrono::steady_clock;
static constexpr uint64_t SEED=0xB0D2A018ULL;
static inline uint64_t mix64(uint64_t x){x+=0x9e3779b97f4a7c15ULL;x=(x^(x>>30))*0xbf58476d1ce4e5b9ULL;x=(x^(x>>27))*0x94d049bb133111ebULL;return x^(x>>31);} 
static inline uint64_t fnv1a(const std::string&s,uint64_t h=1469598103934665603ULL){for(unsigned char c:s){h^=c;h*=1099511628211ULL;}return h;}
struct A{uint32_t rho;uint16_t phi,theta,f;uint64_t fp;};
static inline A enc(const std::string&k,uint32_t M){uint64_t h0=mix64(fnv1a(k)),h1=mix64(h0^0xD6E8FEB86659FD93ULL),h2=mix64(h1^0xA5A35625D3E7E5B9ULL),h3=mix64(h2^0x9E3779B97F4A7C15ULL);return{uint32_t(h0%M),uint16_t(h1),uint16_t(h2),uint16_t(h3),mix64(h0^(h1<<1)^(h2>>1)^h3)};}
struct R{uint64_t fp,val;uint16_t phi,theta,f;};
struct Meta{uint8_t depth=1;uint32_t occ=0,max_phi=0,max_pt=0;double probe=0;uint64_t generation=1;};
struct P{std::vector<R> rec;std::unordered_map<uint16_t,std::vector<uint32_t>> z2;std::unordered_map<uint32_t,std::vector<uint32_t>> z3;std::unordered_map<uint64_t,std::vector<uint32_t>> z4;Meta meta;};
static inline uint32_t pt(uint16_t p,uint16_t t){return(uint32_t(p)<<16)|t;} static inline uint64_t ptf(uint16_t p,uint16_t t,uint16_t f){return(uint64_t(p)<<32)|(uint64_t(t)<<16)|f;}
enum class Mode{RHO_FP,RHO_PHI_FP,RHO_THETA_FP,RHO_PHI_THETA_FP,FIXED3,FIXED4,ADAPT_NOMEM,ADAPT_META,ADAPT_META_CACHE,SIMPLE_CACHE,FREQ_COUNTER};
static const char* mn(Mode m){switch(m){case Mode::RHO_FP:return"rho+fp";case Mode::RHO_PHI_FP:return"rho+phi+fp";case Mode::RHO_THETA_FP:return"rho+theta+fp";case Mode::RHO_PHI_THETA_FP:return"rho+phi+theta+fp";case Mode::FIXED3:return"fixed_z123";case Mode::FIXED4:return"fixed_z1234";case Mode::ADAPT_NOMEM:return"adaptive_no_memory";case Mode::ADAPT_META:return"adaptive_metadata";case Mode::ADAPT_META_CACHE:return"adaptive_metadata_cache";case Mode::SIMPLE_CACHE:return"simple_cache";case Mode::FREQ_COUNTER:return"frequency_counter";}return"?";}
struct LS{uint64_t z1=0,z2=0,z3=0,z4=0,candidates=0,cache_hits=0;};struct Stat{double mean=0,med=0,p95=0,p99=0,max=0,tput=0;};
class DB{uint32_t M,t1=12,t2=48,t3=8;Mode mode;std::vector<P> ps;struct CE{uint64_t fp=0,val=0;bool valid=false;};mutable std::vector<CE> cache;mutable std::vector<uint64_t> freq;
 void build_z2(P&p){if(!p.z2.empty())return;for(uint32_t i=0;i<p.rec.size();++i)p.z2[p.rec[i].phi].push_back(i);}void build_z3(P&p){if(!p.z3.empty())return;for(uint32_t i=0;i<p.rec.size();++i)p.z3[pt(p.rec[i].phi,p.rec[i].theta)].push_back(i);}void build_z4(P&p){if(!p.z4.empty())return;for(uint32_t i=0;i<p.rec.size();++i)p.z4[ptf(p.rec[i].phi,p.rec[i].theta,p.rec[i].f)].push_back(i);} 
 static bool scan(const P&p,const std::vector<uint32_t>*ids,uint64_t fp,uint64_t&v,LS&s,int d){if(!ids)return false;if(d==2)s.z2++;else if(d==3)s.z3++;else s.z4++;s.candidates+=ids->size();for(auto i:*ids)if(p.rec[i].fp==fp){v=p.rec[i].val;return true;}return false;}
 bool z1(const P&p,uint64_t fp,uint64_t&v,LS&s)const{s.z1++;s.candidates+=p.rec.size();for(auto&r:p.rec)if(r.fp==fp){v=r.val;return true;}return false;}
public:DB(uint32_t m,Mode md):M(m),mode(md),ps(m),cache((md==Mode::SIMPLE_CACHE||md==Mode::ADAPT_META_CACHE)?4096:0),freq(md==Mode::FREQ_COUNTER?m:0){}
 void build(const std::vector<std::string>&ks){std::vector<uint32_t>cnt(M);for(auto&k:ks)cnt[enc(k,M).rho]++;for(uint32_t i=0;i<M;++i)ps[i].rec.reserve(cnt[i]);for(uint64_t i=0;i<ks.size();++i){auto a=enc(ks[i],M);ps[a.rho].rec.push_back({a.fp,i,a.phi,a.theta,a.f});}
  for(auto&p:ps){p.meta.occ=p.rec.size();if(mode==Mode::RHO_PHI_FP||mode==Mode::FIXED3||mode==Mode::FIXED4||mode==Mode::ADAPT_NOMEM)build_z2(p);if(mode==Mode::RHO_PHI_THETA_FP||mode==Mode::FIXED3||mode==Mode::FIXED4||mode==Mode::ADAPT_NOMEM)build_z3(p);if(mode==Mode::FIXED4)build_z4(p);
   if(mode==Mode::ADAPT_META||mode==Mode::ADAPT_META_CACHE){if(p.rec.size()<=t1){p.meta.depth=1;continue;}build_z2(p);uint32_t mx=0;uint64_t ss=0;for(auto&kv:p.z2){mx=std::max<uint32_t>(mx,kv.second.size());ss+=uint64_t(kv.second.size())*kv.second.size();}p.meta.max_phi=mx;p.meta.probe=p.rec.empty()?0:double(ss)/p.rec.size();if(mx<=t3){p.meta.depth=2;}else{build_z3(p);uint32_t m3=0;for(auto&kv:p.z3)m3=std::max<uint32_t>(m3,kv.second.size());p.meta.max_pt=m3;p.meta.depth=3;}}
  }}
 bool get(const std::string&k,uint64_t&v,LS&s)const{auto a=enc(k,M);const auto&p=ps[a.rho];if(!cache.empty()){auto&ce=cache[a.fp%cache.size()];if(ce.valid&&ce.fp==a.fp){v=ce.val;s.cache_hits++;return true;}}if(!freq.empty())freq[a.rho]++;bool ok=false;switch(mode){case Mode::RHO_FP:case Mode::SIMPLE_CACHE:case Mode::FREQ_COUNTER:ok=z1(p,a.fp,v,s);break;case Mode::RHO_PHI_FP:{auto it=p.z2.find(a.phi);ok=scan(p,it==p.z2.end()?nullptr:&it->second,a.fp,v,s,2);break;}case Mode::RHO_THETA_FP:{s.z2++;s.candidates+=p.rec.size();for(auto&r:p.rec)if(r.theta==a.theta&&r.fp==a.fp){v=r.val;ok=true;break;}break;}case Mode::RHO_PHI_THETA_FP:{auto it=p.z3.find(pt(a.phi,a.theta));ok=scan(p,it==p.z3.end()?nullptr:&it->second,a.fp,v,s,3);break;}case Mode::FIXED3:{s.z1++;s.z2++;auto it=p.z3.find(pt(a.phi,a.theta));ok=scan(p,it==p.z3.end()?nullptr:&it->second,a.fp,v,s,3);break;}case Mode::FIXED4:{s.z1++;s.z2++;s.z3++;auto it=p.z4.find(ptf(a.phi,a.theta,a.f));ok=scan(p,it==p.z4.end()?nullptr:&it->second,a.fp,v,s,4);break;}case Mode::ADAPT_NOMEM:{uint8_t d=p.rec.size()<=t1?1:(p.rec.size()<=t2?2:3);if(d==1)ok=z1(p,a.fp,v,s);else if(d==2){auto it=p.z2.find(a.phi);ok=scan(p,it==p.z2.end()?nullptr:&it->second,a.fp,v,s,2);}else{auto it=p.z3.find(pt(a.phi,a.theta));ok=scan(p,it==p.z3.end()?nullptr:&it->second,a.fp,v,s,3);}break;}case Mode::ADAPT_META:case Mode::ADAPT_META_CACHE:{uint8_t d=p.meta.depth;if(d==1)ok=z1(p,a.fp,v,s);else if(d==2){auto it=p.z2.find(a.phi);ok=scan(p,it==p.z2.end()?nullptr:&it->second,a.fp,v,s,2);}else{auto it=p.z3.find(pt(a.phi,a.theta));ok=scan(p,it==p.z3.end()?nullptr:&it->second,a.fp,v,s,3);}break;}}
 if(ok&&!cache.empty())cache[a.fp%cache.size()]={a.fp,v,true};return ok;}
 size_t bytes()const{size_t b=ps.capacity()*sizeof(P)+cache.capacity()*sizeof(CE)+freq.capacity()*sizeof(uint64_t);for(auto&p:ps){b+=p.rec.capacity()*sizeof(R);for(auto&kv:p.z2)b+=sizeof(kv)+kv.second.capacity()*4;for(auto&kv:p.z3)b+=sizeof(kv)+kv.second.capacity()*4;for(auto&kv:p.z4)b+=sizeof(kv)+kv.second.capacity()*4;}return b;}
 void dist(double&mean,size_t&mx,double&var,double&ent)const{double total=0;for(auto&p:ps)total+=p.rec.size();mean=total/M;mx=0;var=ent=0;for(auto&p:ps){double x=p.rec.size();mx=std::max(mx,p.rec.size());var+=(x-mean)*(x-mean);if(x){double q=x/total;ent-=q*std::log2(q);}}var/=M;}
};
static std::vector<std::string> keys(const std::string&w,size_t N,uint32_t M){std::vector<std::string>o;o.reserve(N);std::mt19937_64 r(SEED);if(w=="prefix")for(size_t i=0;i<N;++i)o.push_back("TENANT_SHARED_PREFIX_"+std::to_string(i));else if(w=="uuid")for(size_t i=0;i<N;++i){uint64_t a=r(),b=r();char s[64];std::snprintf(s,sizeof(s),"%08x-%04x-%04x-%04x-%012llx",(unsigned)(a>>32),(unsigned)(a>>16),(unsigned)a,(unsigned)(b>>48),(unsigned long long)(b&0xffffffffffffULL));o.emplace_back(s);}else if(w=="random")for(size_t i=0;i<N;++i)o.push_back("R"+std::to_string(r())+"_"+std::to_string(r()));else if(w=="hotrho"){uint32_t hot=std::max(1u,M/32);uint64_t c=0;while(o.size()<N){auto k="H"+std::to_string(c++);if(enc(k,M).rho<hot)o.push_back(k);}}else for(size_t i=0;i<N;++i)o.push_back("K_"+std::to_string(i));return o;}
static std::vector<size_t> queries(const std::string&w,size_t N,size_t Q){std::vector<size_t>q;q.reserve(Q);std::mt19937_64 r(SEED^0x55aa);if(w=="zipf"){std::uniform_real_distribution<double>u(0,1);for(size_t i=0;i<Q;++i)q.push_back(std::min(N-1,size_t(std::pow(u(r),4)*N)));}else{std::uniform_int_distribution<size_t>d(0,N-1);for(size_t i=0;i<Q;++i)q.push_back(d(r));}return q;}
static Stat bench(DB&db,const std::vector<std::string>&ks,const std::vector<size_t>&qs,LS&s){std::vector<double>l;l.reserve(qs.size());volatile uint64_t sink=0;auto A=Clock::now();for(auto i:qs){auto a=Clock::now();uint64_t v=0;if(db.get(ks[i],v,s))sink^=v;auto b=Clock::now();l.push_back(std::chrono::duration<double,std::micro>(b-a).count());}auto B=Clock::now();std::sort(l.begin(),l.end());auto p=[&](double x){return l[size_t(x*(l.size()-1))];};return{std::accumulate(l.begin(),l.end(),0.0)/l.size(),p(.5),p(.95),p(.99),l.back(),qs.size()/std::chrono::duration<double>(B-A).count()};}
int main(int argc,char**argv){size_t N=100000,Q=50000;uint32_t M=2048;std::string only="";for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--n")N=std::stoull(argv[++i]);else if(a=="--q")Q=std::stoull(argv[++i]);else if(a=="--buckets")M=std::stoul(argv[++i]);else if(a=="--workload")only=argv[++i];}
 std::vector<std::string>ws=only.empty()?std::vector<std::string>{"sequential","prefix","uuid","random","zipf","hotrho"}:std::vector<std::string>{only};std::vector<Mode>ms={Mode::RHO_FP,Mode::RHO_PHI_FP,Mode::RHO_THETA_FP,Mode::RHO_PHI_THETA_FP,Mode::FIXED3,Mode::FIXED4,Mode::ADAPT_NOMEM,Mode::ADAPT_META,Mode::SIMPLE_CACHE,Mode::FREQ_COUNTER,Mode::ADAPT_META_CACHE};
 std::cout<<"workload,N,M,mode,build_s,mean_us,median_us,p95_us,p99_us,max_us,throughput_ops_s,bytes_per_record,mean_occ,max_occ,occ_variance,entropy,z1_pct,z2_pct,z3_pct,z4_pct,avg_candidates,cache_hit_pct\n";
 for(auto&w:ws){auto kw=(w=="zipf"?"sequential":w);auto ks=keys(kw,N,M);auto qs=queries(w,N,Q);for(auto m:ms){DB db(M,m);auto b0=Clock::now();db.build(ks);auto b1=Clock::now();LS ls;auto st=bench(db,ks,qs,ls);double mean,var,ent;size_t mx;db.dist(mean,mx,var,ent);double route=std::max<uint64_t>(1,ls.z1+ls.z2+ls.z3+ls.z4);std::cout<<w<<','<<N<<','<<M<<','<<mn(m)<<','<<std::chrono::duration<double>(b1-b0).count()<<','<<st.mean<<','<<st.med<<','<<st.p95<<','<<st.p99<<','<<st.max<<','<<st.tput<<','<<double(db.bytes())/N<<','<<mean<<','<<mx<<','<<var<<','<<ent<<','<<100.0*ls.z1/route<<','<<100.0*ls.z2/route<<','<<100.0*ls.z3/route<<','<<100.0*ls.z4/route<<','<<double(ls.candidates)/Q<<','<<100.0*ls.cache_hits/Q<<"\n";}}
}
